   120  static inline uint32_t
   121  ucl_hash_caseless_func (const ucl_object_t *o)
   122  {
   123          unsigned len = o->keylen;
   124          unsigned leftover = o->keylen % 8;
   125          unsigned fp, i;
   126          const uint8_t* s = (const uint8_t*)o->key;
   127          union {
   128                  struct {
   129                          unsigned char c1, c2, c3, c4, c5, c6, c7, c8;
   130                  } c;
   131                  uint64_t pp;
   132          } u;
   133          uint64_t r;
   134
   135          fp = len - leftover;
   136          r = ucl_hash_seed ();
   137
   138          for (i = 0; i != fp; i += 8) {
   139                  u.c.c1 = s[i], u.c.c2 = s[i + 1], u.c.c3 = s[i + 2], u.c.c4 = s[i + 3];
   140                  u.c.c5 = s[i + 4], u.c.c6 = s[i + 5], u.c.c7 = s[i + 6], u.c.c8 = s[i + 7];
   141                  u.c.c1 = lc_map[u.c.c1];
   142                  u.c.c2 = lc_map[u.c.c2];
   143                  u.c.c3 = lc_map[u.c.c3];
   144                  u.c.c4 = lc_map[u.c.c4];
   145                  u.c.c5 = lc_map[u.c.c5];
   146                  u.c.c6 = lc_map[u.c.c6];
   147                  u.c.c7 = lc_map[u.c.c7];
   148                  u.c.c8 = lc_map[u.c.c8];
   149                  r = mum_hash_step (r, u.pp);
   150          }
   151
   152          u.pp = 0;
   153          switch (leftover) {
   154          case 7:
   155                  u.c.c7 = lc_map[(unsigned char)s[i++]];
   156                  /* FALLTHRU */
   157          case 6:
   158                  u.c.c6 = lc_map[(unsigned char)s[i++]];
   159                  /* FALLTHRU */
   160          case 5:
   161                  u.c.c5 = lc_map[(unsigned char)s[i++]];
   162                  /* FALLTHRU */
   163          case 4:
   164                  u.c.c4 = lc_map[(unsigned char)s[i++]];
   165                  /* FALLTHRU */
   166          case 3:
   167                  u.c.c3 = lc_map[(unsigned char)s[i++]];
   168                  /* FALLTHRU */
   169          case 2:
   170                  u.c.c2 = lc_map[(unsigned char)s[i++]];
   171                  /* FALLTHRU */
   172          case 1:
   173                  u.c.c1 = lc_map[(unsigned char)s[i]];
   174                  r = mum_hash_step (r, u.pp);
   175                  break;
   176          }
   177
   178          return mum_hash_finish (r);
   179  }
