   195
   196                  for (i = 0; i != fp; i += 4) {
   197                          c1 = s[i], c2 = s[i + 1], c3 = s[i + 2], c4 = s[i + 3];
   198                          cmp1.c[0] = lc_map[c1];
   199                          cmp1.c[1] = lc_map[c2];
   200                          cmp1.c[2] = lc_map[c3];
   201                          cmp1.c[3] = lc_map[c4];
   202
   203                          c1 = d[i], c2 = d[i + 1], c3 = d[i + 2], c4 = d[i + 3];
   204                          cmp2.c[0] = lc_map[c1];
   205                          cmp2.c[1] = lc_map[c2];
   206                          cmp2.c[2] = lc_map[c3];
   207                          cmp2.c[3] = lc_map[c4];
   208
   209                          if (cmp1.n != cmp2.n) {
   210                                  return 0;
   211                          }
   212                  }
   213
   214                  while (leftover > 0) {
   215                          if (lc_map[(unsigned char)s[i]] != lc_map[(unsigned char)d[i]]) {
   216                                  return 0;
   217                          }
   218
   219                          leftover--;
   220                          i++;
